1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.util.UUID;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	
11	/**
12	 * Assigns a shared {@code householdId} when a create-owner request opts in with
13	 * {@code sharesHousehold} and an existing owner shares its household: same last name
14	 * (compared case-insensitively with runs of whitespace collapsed to a single space) and
15	 * same address (compared in the normalized form of {@link AddressNormalizer}), the same
16	 * identity {@link RejectDuplicateHousehold} uses. Both the new owner and
17	 * every existing household member are assigned the same identifier, derived deterministically
18	 * from the normalized last name and address, so members always agree on it and it never
19	 * changes as more join.
20	 *
21	 * <p>Runs after {@link BuildOwner} (so the Owner exists) and within the create transaction
22	 * (so any backfilled members commit with the new owner). When {@code sharesHousehold} is not
23	 * set, or no existing owner shares the household, no id is assigned.
24	 */
25	public class AssignHousehold {
26	
27	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
28	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return;
30	        }
31	        String lastName = normalize(owner.getLastName());
32	        String address = AddressNormalizer.normalize(owner.getAddress());
33	        String householdId = householdId(lastName, address);
34	        boolean shared = false;
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (normalize(existing.getLastName()).equals(lastName)
37	                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
38	                shared = true;
