8	
9	/** business-day: the default registration date must fall on a business day (a weekend rolls
10	 * forward to Monday). Can't force the server's clock black-box, so assert the invariant that holds
11	 * every day: the default registrationDate is never a Saturday or Sunday. */
12	class AcceptanceTest extends AcceptanceBase {
13	
14		@Test
15		void coreDefaultDateIsBusinessDay() throws Exception {
16			int id = createOwnerOk(ownerNode());
17			DayOfWeek dow = LocalDate.parse(fetchOwner(id).get("registrationDate").asText()).getDayOfWeek();
18			assertTrue(dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY, dow.toString());
19		}
20	}
